func NewSegmentTree(N int) *SegmentTree {
    n := N
    for (n & (n - 1)) != 0 {
        n++
    }
    return &SegmentTree{n: n, tree: make([]int, 2*n)}
}

func (st *SegmentTree) Update(i, val int) {
    st.tree[st.n+i] = val
    j := (st.n + i) >> 1
    for j >= 1 {
        st.tree[j] = max(st.tree[j<<1], st.tree[j<<1|1])
        j >>= 1
    }
}

func (st *SegmentTree) Query(l, r int) int {
    if l > r {
        return 0
    }
    res := -1 << 31
    l += st.n
    r += st.n + 1
    for l < r {
        if l&1 == 1 {
            if st.tree[l] > res {
                res = st.tree[l]
            }
            l++
        }
        if r&1 == 1 {
            r--
            if st.tree[r] > res {
                res = st.tree[r]
            }
        }
        l >>= 1
        r >>= 1
    }
    return res
}

